def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    doc = app.activeDocument
    des = adsk.fusion.Design.cast(doc.products.itemByProductType("DesignProductType"))
    root = des.rootComponent
    def dump(b, pfx=""):
        bb = b.boundingBox
        print(pfx, b.name, [round(v*10,3) for v in bb.minPoint.asArray()], [round(v*10,3) for v in bb.maxPoint.asArray()])
    for b in root.bRepBodies: dump(b, "root")
    for occ in root.allOccurrences:
        for b in occ.bRepBodies: dump(b, "occ:"+occ.name)
    for f in root.features: print("feat:", f.name)
    for occ in root.allOccurrences:
        for f in occ.component.features: print("feat", occ.name, f.name)
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType("CAMProductType"))
    s = cam.setups.item(0)
    for i in range(s.parameters.count):
        pr = s.parameters.item(i)
        try: print("  param:", pr.name, "=", pr.expression)
        except Exception: print("  param:", pr.name, "(no expr)")
    return None

